{
  "findings": [
    {
      "check_id": "CKV_AZURE_25",
      "title": "Threat Detection types not set to All",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The 'disabled_alerts' list explicitly disables 'Sql_Injection' and 'Data_Exfiltration' alerts, violating the requirement to have all threat detection types enabled."
    },
    {
      "check_id": "CKV_AZURE_27",
      "title": "Email service and co-administrators not enabled",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The 'email_account_admins' attribute is missing or not set to true, meaning service and co-administrators will not receive security alerts."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  disabled_alerts = []\n  retention_days  = 20\n  email_addresses = [\"securityengineer@bridgecrew.io\"]\n  email_account_admins = true\n}",
  "fix_summary": "Removed 'Sql_Injection' and 'Data_Exfiltration' from the 'disabled_alerts' list to ensure all threat detection types are enabled (CKV_AZURE_25). Added 'email_account_admins = true' to ensure service and co-administrators receive alerts (CKV_AZURE_27)."
}
